 {"id":"V1553_CLASSICAL","control_role":"V1553_PERMUTATION_CLASSICAL","carrier":[0,1,2,3],"operations":[[0,1,2,3],[1,0,3,2]],"operational_table":_table([_corr(),_corr(),_corr(),_corr()])},
