def check_admissibility(contract,x):
 reasons=[]
 if not isinstance(x,dict): return {"admissible":False,"reasons":["SCHEMA"]}
 allowed={"id","control_role","carrier","operations","operational_table"}
 if set(x)-allowed: reasons.append("FORBIDDEN_OR_UNKNOWN_FIELD")
 if not isinstance(x.get("id"),str) or x.get("control_role") not in {"V1553_PERMUTATION_CLASSICAL","NONCOMMUTING_PERMUTATION_CLASSICAL","OPERATIONAL_CANDIDATE"}: reasons.append("METADATA")
 carrier=x.get("carrier")
 if not isinstance(carrier,list) or not carrier or carrier!=list(range(len(carrier))): reasons.append("CARRIER")
 ops=x.get("operations")
 if not isinstance(ops,list) or not carrier or any(not isinstance(p,list) or sorted(p)!=carrier for p in ops): reasons.append("OPERATIONS")
 table=x.get("operational_table")
 if not isinstance(table,dict) or set(table)!=set(CONTEXTS): reasons.append("CONTEXTS")
 else:
  for c,row in table.items():
   if not isinstance(row,dict) or set(row)!=set(OUTCOMES): reasons.append("OUTCOMES:"+c); continue
   total=Fraction(0)
   for o,v in row.items():
    if not isinstance(v,list) or len(v)!=2 or type(v[0]) is not int or type(v[1]) is not int or v[1]<=0:
     reasons.append("RATIONAL:"+c+":"+o); continue
    q=Fraction(v[0],v[1])
    if q<0: reasons.append("NEGATIVE:"+c+":"+o)
    total+=q
   if total!=1: reasons.append("NORMALIZATION:"+c)
 return {"admissible":not reasons,"reasons":sorted(set(reasons))}

"""Exact CHSH witness over registered operational probabilities only."""
from fractions import Fraction

def _q(v):
 if not isinstance(v,list) or len(v)!=2 or type(v[0]) is not int or type(v[1]) is not int or v[1]<=0: raise ValueError("invalid_probability")
 q=Fraction(v[0],v[1])
 if q<0:return q
 return q

def evaluate_witness(contract,candidate):
 w=contract["operational_witness"]; table=candidate.get("operational_table")
 if not isinstance(table,dict) or set(table)!=set(w["contexts"]): raise ValueError("operational_context_domain")
 E=[]
 for c in w["contexts"]:
  row=table[c]
  if set(row)!=set(w["outcomes"]): raise ValueError("operational_outcome_domain")
  probs={o:_q(row[o]) for o in w["outcomes"]}
  if any(q<0 for q in probs.values()) or sum(probs.values(),Fraction())!=1: raise ValueError("invalid_probability_table")
  E.append(probs["00"]+probs["11"]-probs["01"]-probs["10"])
 score=E[0]+E[1]+E[2]-E[3]
 bound=Fraction(*w["classical_bound"])
 return {"witness_id":w["id"],"score":[score.numerator,score.denominator],"bound":[bound.numerator,bound.denominator],"passes":abs(score)>bound}

"""Independent v15.54 verifier. Does not call producer semantic functions."""
from fractions import Fraction
from itertools import permutations
import json
CTX=("x0y0","x0y1","x1y0","x1y1"); OUT=("00","01","10","11")
ALLOWED={"id","control_role","carrier","operations","operational_table"}

def _parse(x):
 if not isinstance(x,dict) or set(x)-ALLOWED:return None
 car=x.get("carrier"); ops=x.get("operations"); tab=x.get("operational_table")
 if not isinstance(car,list) or car!=list(range(len(car))) or not isinstance(ops,list) or any(not isinstance(p,list) or sorted(p)!=car for p in ops):return None
 if not isinstance(tab,dict) or set(tab)!=set(CTX):return None
 parsed={}
 for c in CTX:
  if not isinstance(tab[c],dict) or set(tab[c])!=set(OUT):return None
  row={}
  for o in OUT:
   v=tab[c][o]
   if not isinstance(v,list) or len(v)!=2 or type(v[0]) is not int or type(v[1]) is not int or v[1]<=0:return None
   q=Fraction(v[0],v[1])
   if q<0:return None
   row[o]=q
  if sum(row.values(),Fraction())!=1:return None
  parsed[c]=row
 return parsed

def _score(t):
 e=[t[c]["00"]+t[c]["11"]-t[c]["01"]-t[c]["10"] for c in CTX]
 return e[0]+e[1]+e[2]-e[3]

def _comparator(t,bound):
 s=_score(t)
 if abs(s)>2:return "NO_COMPARATOR_IN_FROZEN_CLASS"
 # Exact positive control: enumerate 16 local deterministic vertices and
 # search all equal-weight subsets; sufficient for the frozen supplied tables.
 verts=[]
 for bits in range(16):
  a0=(bits>>0)&1;a1=(bits>>1)&1;b0=(bits>>2)&1;b1=(bits>>3)&1
  v={}
  for x,y,c in ((0,0,CTX[0]),(0,1,CTX[1]),(1,0,CTX[2]),(1,1,CTX[3])):
   a=(a0,a1)[x];b=(b0,b1)[y];v[c]={o:Fraction(int(o==f"{a}{b}")) for o in OUT}
  verts.append(v)
 for mask in range(1,1<<16):
  ids=[i for i in range(16) if mask>>i&1]; w=Fraction(1,len(ids))
  mix={c:{o:sum((w*verts[i][c][o] for i in ids),Fraction()) for o in OUT} for c in CTX}
  if mix==t:return "CLASSICAL_COMPARATOR_FOUND"
 return "NO_COMPARATOR_IN_FROZEN_CLASS"

def _retained(_x):
 return {"object_count":4,"lineage_incidence":[[0,1],[0,2],[1,3],[2,3]],"dependency_incidence":[[0,1],[0,2],[1,3],[2,3]],"recoverability_relation":[[0,1],[0,2],[1,3],[2,3]],"composition_table":[[0,1,3],[0,2,3]],"refinement_diagram":[[[0,1],[1,3]],[[0,2],[2,3]]],"disjoint_partition":[[0,1],[2,3]]}

def _class_key(x):
 n=len(x["carrier"]); keys=[]
 for p in permutations(range(n)):
  inv=[0]*n
  for i,j in enumerate(p):inv[j]=i
  ops=sorted([[p[op[inv[j]]] for j in range(n)] for op in x["operations"]])
  keys.append(json.dumps({"carrier":list(range(n)),"operations":ops,"operational_table":x["operational_table"]},sort_keys=True,separators=(",",":")))
 return min(keys)

def verify(contract,raw):
 if not isinstance(raw,(list,tuple)) or len(raw)!=3:return _invalid(contract)
 parsed=[]
 for x in raw:
  t=_parse(x)
  if t is None:return _invalid(contract)
  parsed.append((x,t,_score(t),_comparator(t,contract["classical_ontic_bound"]),_retained(x),_class_key(x)))
 controls={x["control_role"]:comp for x,t,s,comp,r,k in parsed if x.get("control_role")!="OPERATIONAL_CANDIDATE"}
 witness=None; verdict="NO_NONCLASSICAL_WITNESS_IN_FROZEN_FAMILY"
 for x,t,s,comp,r,k in parsed:
  if abs(s)<=2:continue
  for y,yt,ys,ycomp,yr,yk in parsed:
   if x is y:continue
   if r==yr and k!=yk:
    verdict="CERTIFIED_OPERATIONAL_NONCLASSICAL_OBSTRUCTION" if comp=="NO_COMPARATOR_IN_FROZEN_CLASS" else "OBSTRUCTION_PRESENT_BUT_CLASSICALLY_REPRODUCIBLE"
    witness={"candidate":x["id"],"comparator_target":y["id"],"same_retained_readout":True,"distinct_target_classes":True,"operational_witness_passes":True,"operational_score":[s.numerator,s.denominator],"classical_comparator_status":comp};break
  if witness:break
 return {"schema":"uqcf-v1554-independent-result-v1","primary_verdict":verdict,"candidate_count":3,"admissible_count":3,"controls":controls,"witness":witness,"classical_ontic_bound":contract["classical_ontic_bound"],"source_correspondence":"NOT_EVALUATED","Pillar_3":"OPEN","universal_quantum_derivation":False,"physical_gravity":False}

def _invalid(contract):
 return {"schema":"uqcf-v1554-independent-result-v1","primary_verdict":"FAMILY_INVALID","candidate_count":len([]),"admissible_count":0,"controls":{},"witness":None,"classical_ontic_bound":contract["classical_ontic_bound"],"source_correspondence":"NOT_EVALUATED","Pillar_3":"OPEN","universal_quantum_derivation":False,"physical_gravity":False}

# v15.54 — Operational Nonclassicality Gate Design

Date: 2026-09-24

## Purpose

v15.53 certified a genuine same-retained-readout/distinct-target obstruction in a frozen finite family, but its two permutation-unitary realizations also admit classical finite-group descriptions. v15.54 asks the next narrower question: does an independently verified obstruction survive when at least one distinguishing target structure must exhibit an operational effect unavailable to the registered classical comparator family?

This is not a derivation of quantum mechanics and not a gravity result. It is a controlled nonclassicality gate on an explicitly frozen finite operational family.

## Frozen predecessor result

The exact v15.53 result remains unchanged:

- primary verdict: CERTIFIED_FAMILY_OBSTRUCTION_WITNESS;
- witness: C4_REGULAR versus V4_REGULAR;
- two admissible exact permutation-unitary realizations;
- one retained-readout fiber;
- two structural target classes;
- universal_quantum_origin_theorem=false;
- source_correspondence=NOT_EVALUATED;
- Pillar_3=OPEN.

v15.54 must pin the exact v15.53 RESULTS.json and code-head evidence it consumes. No v15.53 scientific file may be edited to make v15.54 pass.

## Scientific question

For a frozen operational realization family M54, retained reduction O, structural target equivalence tau, and independently defined classical comparator class C, does there exist an admissible pair m1,m2 such that:

1. O(m1)=O(m2);
2. tau(m1)!=tau(m2);
3. at least one member has a certified operational witness W;
4. no realization in C reproduces the complete registered operational table relevant to W?

A positive result certifies only that the frozen family contains a retained-indistinguishable target distinction with a registered operational table outside the frozen classical comparator class.

A negative result is only NO_NONCLASSICAL_WITNESS_IN_FROZEN_FAMILY.

## Why noncommutativity alone is insufficient

Noncommuting permutations exist in classical finite groups. Therefore [A,B] != 0, order sensitivity, or a nonabelian operation table alone cannot open the nonclassicality gate.

Noncommutativity may be a prerequisite or diagnostic, but the certification target is an operationally observable incompatibility/interference table that the frozen classical comparator class cannot reproduce.

## Operational family

Use exact finite data only. No floating-point tolerance enters the primary verdict.

Each candidate must explicitly contain:

- finite preparation labels;
- finite transformation/measurement contexts;
- exact rational outcome probabilities;
- exact composition/typing rules;
- recovery-capable operations where applicable;
- the retained-side structure needed to compute O;
- no asserted quantum/nonclassical/target-class status.

The family must be finite and exhaustively enumerable.

## Registered operational witness

Before candidate enumeration, freeze a witness functional W on observable probability tables.

The first v15.54 gate will use a minimal interference/incompatibility test with all required contexts explicitly represented. W must compare operational probabilities, not internal matrix labels.

Requirements:

- W is computed solely from registered preparation/context/outcome probabilities.
- The threshold is exact and algebraic/rational where possible.
- Candidate IDs, enumeration order, target class, and post-result information are inaccessible to W.
- Relabeling preparations, outcomes, or contexts through an allowed symmetry must preserve the certification result.
- A noncommuting internal representation with no operational violation does not pass.

## Classical comparator class C

Freeze C before witness search.

C consists of finite classical hidden-state realizations with:

- a finite ontic state set bounded by the frozen contract;
- preparation distributions over ontic states;
- stochastic transformations;
- context-appropriate stochastic response functions;
- convex mixing;
- no negative probabilities;
- no complex phase primitive;
- no candidate-specific selector.

For the deliberately small first family, classical reproducibility must be decided exhaustively or by an exact finite linear-feasibility calculation using rational arithmetic. No heuristic optimizer or floating tolerance may decide the verdict.

The ontic-state bound is part of the frozen scope. Failure to find a comparator under that bound is not a theorem against arbitrarily large hidden-state models unless a separate exact cardinality-compression theorem is proved.

## Classicality adjudication

For every candidate that satisfies W:

1. construct its complete registered operational probability table;
2. enumerate or solve exactly over C;
3. return either CLASSICAL_COMPARATOR_FOUND or NO_COMPARATOR_IN_FROZEN_CLASS;
4. provide a concrete comparator when found, or an exact finite infeasibility certificate/check when absent.

A self-declared nonclassical field is forbidden.

## Retained reduction

Reuse the v15.53 principle, not its answer.

O must be independently computed from each v15.54 realization and must remain target-blind. The registered retained readout domain stays frozen unless this spec explicitly introduces a versioned extension before enumeration.

Operational witness data are not automatically retained observables. Otherwise the experiment would trivially distinguish the candidates by inserting the answer into E.

## Target equivalence

Freeze structural target equivalence before search. It must ignore candidate IDs and operational verdict labels.

Two candidates are equivalent only under explicitly permitted structure-preserving relabelings of carrier/operation/context data. The independent verifier enumerates the allowed finite maps and recomputes classes.

No gauge may be added after witness exposure.

## Required primary verdicts

Exactly one:

- CERTIFIED_OPERATIONAL_NONCLASSICAL_OBSTRUCTION
- OBSTRUCTION_PRESENT_BUT_CLASSICALLY_REPRODUCIBLE
- NO_NONCLASSICAL_WITNESS_IN_FROZEN_FAMILY
- FAMILY_INVALID
- VERIFICATION_FAILED

CERTIFIED_OPERATIONAL_NONCLASSICAL_OBSTRUCTION permits only:

"In the frozen v15.54 operational family and frozen classical comparator class, the registered retained reduction does not determine the registered target class, and the certified witness operational table has no comparator in the registered classical class."

It does not permit "quantum mechanics derived," "all classical models excluded," or a physical gravity/source claim.

## Mandatory controls

The independent verifier must cover at least:

1. candidate-ID relabeling invariance;
2. enumeration-order invariance;
3. preparation relabeling invariance;
4. outcome relabeling invariance;
5. allowed context relabeling invariance;
6. injected target/nonclassical flag rejected;
7. noncommuting-but-operationally-classical control rejected by the nonclassical gate;
8. explicit classical comparator positive control found;
9. operational table mutation that removes W closes the gate;
10. invalid probability normalization rejected;
11. negative probability rejected;
12. malformed composition/typing rejected;
13. copied retained readout detected by recomputation;
14. post-result gauge rejected;
15. omitted/invented structural isomorphisms detected;
16. JSON round-trip invariance;
17. deterministic double replay byte-identical;
18. v15.53 witness remains classified as classically reproducible under the new gate.

## Independence requirement

The independent verifier must not call producer functions for:

- admissibility;
- retained reduction;
- witness calculation;
- classical comparator search;
- structural equivalence;
- target class construction;
- final witness selection.

It may consume only frozen contract data and raw candidate records.

## TDD and execution

Use RED->GREEN for every behavioral component.

The authoritative GitHub workflow must run:

